        adj[b].push_back(a);
    }

    int ans = 1; // at least one city can have a concert

    // For every possible start of the path
    for (int root = 1; root <= n; ++root) {
        vector<int> lis;                     // tails of LIS
        vector<tuple<int, int, bool>> changes; // (pos, old_val, appended)

        // stack entries: (node, parent, state)
        // state 0 = entering, 1 = exiting
        stack<tuple<int, int, int>> st;
        st.emplace(root, -1, 0);

        while (!st.empty()) {
            auto [u, p, state] = st.top();
            st.pop();

            if (state == 0) { // entering
                // insert r[u] into the current LIS tails
                int pos = lower_bound(lis.begin(), lis.end(), r[u]) - lis.begin();
                bool appended = false;
                int old_val = -1;
                if (pos == (int)lis.size()) {
                    lis.push_back(r[u]);
                    appended = true;
                } else {
                    old_val = lis[pos];
                    lis[pos] = r[u];
                }
                changes.emplace_back(pos, old_val, appended);
                ans = max(ans, (int)lis.size());

                // schedule exit
                st.emplace(u, p, 1);

                // push children (reverse order to simulate natural DFS)
                for (int i = (int)adj[u].size() - 1; i >= 0; --i) {
                    int v = adj[u][i];
                    if (v != p) st.emplace(v, u, 0);
                }
            } else { // exiting
                auto [pos, old_val, appended] = changes.back();
                changes.pop_back();
                if (appended) lis.pop_back();
                else lis[pos] = old_val;
            }
        }
    }

    cout << ans << '\n';
    return 0;
}
