## Solution

The approach is straightforward:

1. **Flatten** the 2D array into a 1D list
2. **Sort** by density (ascending: Oil → Alcohol → Water → Honey)
3. **Reshape** back to the original dimensions, filling row by row from left to right

Here's the JavaScript implementation:

```javascript
function separateLiquids(glass) {
  // Density mapping (lower = floats higher)
  const density = { 'O': 0, 'A': 1, 'W': 2, 'H': 3 };

  // Get dimensions
  const rows = glass.length;
  const cols = glass[0].length;

  // Flatten, sort by density, reshape
  return glass
    .flat()                                    // Flatten to 1D
    .sort((a, b) => density[a] - density[b])   // Sort by density ascending
    .reduce((acc, val, i) => {                 // Reshape back to 2D
      const row = Math.floor(i / cols);
      if (!acc[row]) acc[row] = [];
      acc[row].push(val);
      return acc;
    }, []);
}
```

### How it works:

- **`density`** object assigns a numeric value to each liquid based on its density (0 = lowest density / floats highest, 3 = highest density / sinks lowest)
- **`.flat()`** converts `[['H','H','W','O'], ['W','W','O','W'], ['H','H','O','O']]` into `['H','H','W','O','W','W','O','W','H','H','O','O']`
- **`.sort()`** arranges by density: Oil (0.80) → Alcohol (0.87) → Water (1.00) → Honey (1.36)
- **`.reduce()`** reconstructs the 2D array with the original number of columns

### Example:

```javascript
separateLiquids([
  ['H', 'H', 'W', 'O'],
  ['W', 'W', 'O', 'W'],
  ['H', 'H', 'O', 'O']
]);
// Returns:
// [
//   ['O', 'O', 'O', 'O'],
//   ['W', 'W', 'W', 'W'],
//   ['H', 'H', 'H', 'H']
// ]
```

The note *"If a liquid doesn't fill a row, it floats to the top and to the left"* is automatically satisfied because we sort first (lowest density items come first) and then fill left-to-right, top-to-bottom.

```python
import sys
sys.setrecursionlimit(1000000)

INF = 10**18

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    a = [[0]*m for _ in range(n)]   # a[row][col]
    for i in range(n):
        for j in range(m):
            a[i][j] = int(next(it))

    # column prefix sums
    col_pref = [[0]*n for _ in range(m)]   # col_pref[col][row]
    for j in range(m):
        s = 0
        for i in range(n):
            s += a[i][j]
            col_pref[j][i] = s

    # V[col][i][k] = cost to go from (i,col) to (k,col) vertically, excluding start
    V = [[[0]*n for _ in range(n)] for __ in range(m)]
    for j in range(m):
        pref = col_pref[j]
        for i in range(n):
            for k in range(n):
                if i == k:
                    V[j][i][k] = 0
                else:
                    lo = min(i,k)+1
                    hi = max(i,k)
                    if lo <= hi:
                        V[j][i][k] = pref[hi] - (pref[lo-1] if lo>0 else 0)
                    else:
                        V[j][i][k] = 0

    q = int(next(it))
    queries = []   # list of (r1,c1,r2,c2) after ensuring c1 <= c2
    orig_idx = []
    for qi in range(q):
        r1 = int(next(it)); c1 = int(next(it)); r2 = int(next(it)); c2 = int(next(it))
        if c1 > c2:
            r1, c1, r2, c2 = r2, c2, r1, c1
        queries.append((r1, c1, r2, c2))
        orig_idx.append(qi)

    ans = [0]*q

    # precompute one-step matrices for same-column queries
    # T_right[j][i][k] = cost from (i, j-1) to (k, j)
    T_right = [None]*m   # T_right[j] for j>=1
    for j in range(1, m):
        mat = [[INF]*n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                best = INF
                for s in range(n):
                    val = V[j-1][i][s] + a[s][j] + V[j][s][k]
                    if val < best:
                        best = val
                mat[i][k] = best
        T_right[j] = mat
    # T_left[j][i][k] = cost from (i, j) to (k, j-1)
    T_left = [None]*m   # T_left[j] for j>=1
    for j in range(1, m):
        mat = [[INF]*n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                best = INF
                for s in range(n):
                    val = V[j][i][s] + a[s][j-1] + V[j-1][s][k]
                    if val < best:
                        best = val
                mat[i][k] = best
        T_left[j] = mat

    # split queries into same-column and different-column
    same_col_queries = []
    diff_col_queries = []
    for idx, (r1,c1,r2,c2) in enumerate(queries):
        if c1 == c2:
            same_col_queries.append(idx)
        else:
            diff_col_queries.append(idx)

    # handle same-column queries
    for idx in same_col_queries:
        r1,c1,r2,c2 = queries[idx]
        col = c1
        # direct vertical
        lo = min(r1, r2)
        hi = max(r1, r2)
        best = col_pref[col][hi] - (col_pref[col][lo-1] if lo>0 else 0)
        # via left neighbour
        if col > 0:
            # ans = w[r1][col] + min_t T_left[col][r1][t] + T_right[col][t][r2]
            mat_left = T_left[col]
            mat_right = T_right[col]
            for t in range(n):
                cand = a[r1][col] + mat_left[r1][t] + mat_right[t][r2]
                if cand < best:
                    best = cand
        # via right neighbour
        if col < m-1:
            # ans = w[r1][col] + min_t T_right[col+1][r1][t] + T_left[col+1][t][r2]
            mat_right = T_right[col+1]
            mat_left = T_left[col+1]
            for t in range(n):
                cand = a[r1][col] + mat_right[r1][t] + mat_left[t][r2]
                if cand < best:
                    best = cand
        ans[orig_idx[idx]] = best

    # if no diff queries, output
    if not diff_col_queries:
        out = '\n'.join(str(x) for x in ans)
        sys.stdout.write(out)
        return

    # We will store original answer indices in ans array
    # We'll pass queries as tuples (orig_idx, r1,c1,r2,c2)
    diff_query_list = [(orig_idx[idx],) + queries[idx] for idx in diff_col_queries]

    # Divide and conquer
    def dac(L, R, qlist):
        if not qlist:
            return
        if L == R:
            # should not happen because diff queries have c1 < c2
            return
        M = (L+R)//2
        # ---------- left DP ----------
        left_len = M - L + 1
        left_dp = [[[INF]*n for _ in range(n)] for __ in range(left_len)]
        # column M
        for r in range(n):
            for t in range(n):
                left_dp[M-L][r][t] = V[M][r][t]
        # columns M-1 .. L
        for col in range(M-1, L-1, -1):
            idx = col - L
            Vcol = V[col]
            nxt = left_dp[idx+1]
            cur = left_dp[idx]
            for r in range(n):
                for t in range(n):
                    best = INF
                    for s in range(n):
                        val = Vcol[r][s] + a[s][col+1] + nxt[s][t]
                        if val < best:
                            best = val
                    cur[r][t] = best
        # ---------- right DP ----------
        right_len = R - M + 1
        right_dp = [[[INF]*n for _ in range(n)] for __ in range(right_len)]
        # column M
        for r in range(n):
            for t in range(n):
                right_dp[0][r][t] = V[M][t][r]   # distance from (t,M) to (r,M)
        # columns M+1 .. R
        for col in range(M+1, R+1):
            idx = col - M
            prev = right_dp[idx-1]
            Vcol = V[col]
            cur = right_dp[idx]
            for r in range(n):
                for t in range(n):
                    best = INF
                    for s in range(n):
                        val = prev[s][t] + a[s][col] + Vcol[s][r]
                        if val < best:
                            best = val
                    cur[r][t] = best

        # separate queries
        left_q = []
        right_q = []
        for (orig_i, r1,c1,r2,c2) in qlist:
            if c1 <= M and c2 > M:
                # crossing
                left_mat = left_dp[c1 - L]
                right_mat = right_dp[c2 - M]
                best = INF
                for t in range(n):
                    val = left_mat[r1][t] + right_mat[r2][t]
                    if val < best:
                        best = val
                ans[orig_i] = a[r1][c1] + best
            elif c2 <= M:
                left_q.append((orig_i,r1,c1,r2,c2))
            else:  # c1 > M
                right_q.append((orig_i,r1,c1,r2,c2))
        dac(L, M, left_q)
        dac(M+1, R, right_q)

    dac(0, m-1, diff_query_list)

    out = '\n'.join(str(x) for x in ans)
    sys.stdout.write(out)

if __name__ == "__main__":
    solve()
```

