def solve(a, b):
    def is_prime(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    def has_prime_digits(n):
        for ch in str(n):
            if ch not in '2357':
                return False
        return True

    result = []
    for n in range(a, b):
        if has_prime_digits(n) and not is_prime(n):
            result.append(n)

    return result
```

