def waysToIncreaseLCSBy1(S1, S2):
    N1, N2 = len(S1), len(S2)

    # ---------- forward LCS (prefix) ----------
    dp_f = [[0] * (N2 + 1) for _ in range(N1 + 1)]
    for i in range(1, N1 + 1):
        for j in range(1, N2 + 1):
            if S1[i - 1] == S2[j - 1]:
                dp_f[i][j] = dp_f[i - 1][j - 1] + 1
            else:
                dp_f[i][j] = max(dp_f[i - 1][j], dp_f[i][j - 1])

    # ---------- backward LCS (suffix) ----------
    dp_b = [[0] * (N2 + 1) for _ in range(N1 + 1)]
    for i in range(N1 - 1, -1, -1):
        for j in range(N2 - 1, -1, -1):
            if S1[i] == S2[j]:
                dp_b[i][j] = dp_b[i + 1][j + 1] + 1
            else:
                dp_b[i][j] = max(dp_b[i + 1][j], dp_b[i][j + 1])

    L = dp_f[N1][N2]          # original LCS length
    count = 0

    # ---------- examine every insertion ----------
    for p in range(N1 + 1):            # position to insert
        for c in 'abcdefghijklmnopqrstuvwxyz':
